import base64, os

icons = {
    'mipmap-mdpi/ic_launcher.png': '',
    'mipmap-mdpi/ic_launcher_round.png': '',
    'mipmap-hdpi/ic_launcher.png': '',
    'mipmap-hdpi/ic_launcher_round.png': '',
}

base = r"E:\App Project\Farmnest\android\app\src\main\res"
for rel_path, b64data in icons.items():
    folder, name = rel_path.split("/")
    dst = os.path.join(base, folder, name)
    with open(dst, "wb") as f:
        f.write(base64.b64decode(b64data))
    print(f"Written: {dst}")
print("\nAll icons installed! Now run: npx react-native run-android")
